const crypto = require('crypto');
const item = $input.first();
const headers = Object.fromEntries(Object.entries(item.json.headers || {}).map(([k, v]) => [k.toLowerCase(), String(v)]));
const signature = headers['x-aves-signature'] || '';
const signedAt = headers['x-aves-timestamp'] || '';
const headerEventId = headers['x-aves-event-id'] || '';
const reject = (statusCode, error) => [{ json: { valid: false, statusCode, error } }];
if (!signature || !signedAt || !headerEventId) return reject(401, 'Missing webhook authentication headers');
if (!/^[a-f0-9]{64}$/i.test(signature)) return reject(401, 'Invalid webhook signature');
const signedTime = Date.parse(signedAt);
if (!Number.isFinite(signedTime) || Math.abs(Date.now() - signedTime) > 300000) return reject(401, 'Webhook timestamp is stale or invalid');
let rawBody;
try { rawBody = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8'); } catch { return reject(400, 'Raw request body is unavailable'); }
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('Webhook secret is not configured');
const expected = crypto.createHmac('sha256', secret).update(`${signedAt}.${rawBody}`, 'utf8').digest('hex');
if (!crypto.timingSafeEqual(Buffer.from(signature.toLowerCase(), 'hex'), Buffer.from(expected, 'hex'))) return reject(401, 'Invalid webhook signature');
let envelope;
try { envelope = JSON.parse(rawBody); } catch { return reject(400, 'Malformed JSON body'); }
const allowed = new Set(['patient.created','appointment.requested','appointment.approved','appointment.confirmed','appointment.cancelled','appointment.rescheduled','conversation.handoff_requested','escalation.created','escalation.acknowledged','escalation.resolved']);
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!allowed.has(envelope.event) || !uuid.test(envelope.event_id || '') || !uuid.test(envelope.clinic_id || '') || !Number.isFinite(Date.parse(envelope.timestamp)) || !envelope.data || typeof envelope.data !== 'object' || Array.isArray(envelope.data)) return reject(400, 'Invalid event envelope');
if (envelope.event_id !== headerEventId) return reject(400, 'Event ID header does not match body');
return [{ json: { valid: true, event: envelope.event, event_id: envelope.event_id, clinic_id: envelope.clinic_id, timestamp: envelope.timestamp, data: envelope.data } }];

const e = $('Verify Signature and Envelope').first().json;
const d = e.data;
const to = [...new Set((d.recipients || []).map(r => r.email).filter(Boolean))].join(',');
if (!to) throw new Error('No receptionist recipient supplied for appointment request');
return [{ json: { to, send: true, subject: `New appointment request: ${d.patient_name || d.appointment_id}`, html: `<h2>New appointment request</h2><p><strong>Patient:</strong> ${d.patient_name || 'Not supplied'}</p><p><strong>Contact:</strong> ${d.patient_phone || d.patient_email || 'Not supplied'}</p><p><strong>Doctor:</strong> ${d.doctor_name || 'Not supplied'}</p><p><strong>Requested time:</strong> ${d.start_time}</p><p><strong>Status:</strong> ${d.status}</p><p><strong>Appointment ID:</strong> ${d.appointment_id}</p><p>This request is not confirmed.</p>` } }];

const d = $('Verify Signature and Envelope').first().json.data;
const clinic = [d.clinic_name, d.clinic_phone, d.clinic_email].filter(Boolean).join(' · ');
return [{ json: { to: d.patient_email || '', send: Boolean(d.patient_email), subject: 'Your appointment is confirmed', html: `<h2>Appointment confirmed</h2><p>Your appointment with ${d.doctor_name || 'the clinic'} is confirmed for ${d.start_time}.</p><p>Appointment ID: ${d.appointment_id}</p>${clinic ? `<p>${clinic}</p>` : ''}` } }];

const d = $('Verify Signature and Envelope').first().json.data;
const to = [...new Set((d.recipients || []).map(r => r.email).filter(Boolean))].join(',');
if (!to) throw new Error('No receptionist recipient supplied for handoff');
return [{ json: { to, send: true, subject: `Patient conversation needs staff: ${d.conversation_id}`, html: `<h2>Human handoff requested</h2><p><strong>Conversation ID:</strong> ${d.conversation_id}</p><p><strong>Patient ID:</strong> ${d.patient_id || 'Not linked'}</p><p><strong>Source:</strong> ${d.source || 'Not supplied'}</p>` } }];

const d = $('Verify Signature and Envelope').first().json.data;
const to = [...new Set((d.recipients || []).map(r => r.email).filter(Boolean))].join(',');
if (!to) throw new Error('No escalation recipient supplied');
const urgent = d.severity === 'critical' ? 'CRITICAL: ' : '';
return [{ json: { to, send: true, subject: `${urgent}Dental escalation ${d.escalation_id}`, html: `<h2>${urgent}Clinic escalation</h2><p><strong>Severity:</strong> ${d.severity}</p><p><strong>Reason:</strong> ${d.reason}</p>${d.summary ? `<p><strong>Summary:</strong> ${d.summary}</p>` : ''}<p><strong>Patient:</strong> ${d.patient?.name || 'Not supplied'} · ${d.patient?.phone || d.patient?.email || 'No contact supplied'}</p><p><strong>Conversation ID:</strong> ${d.conversation_id || 'None'}</p><p><strong>Escalation ID:</strong> ${d.escalation_id}</p>` } }];
